# RWDM_MOVE: Move: base point and destination, and a typed relative vector. The script rwdm_move_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_MOVE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_move_script.txt" 2>&1)" || { echo "$RWDM_MOVE_OUT" | tail -40; echo "FAIL RWDM_MOVE_run: script exited non-zero"; fail=1; RWDM_MOVE_OUT=""; }
else
  RWDM_MOVE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_move_script.txt" 2>&1)" || { echo "$RWDM_MOVE_OUT" | tail -40; echo "FAIL RWDM_MOVE_run: script exited non-zero"; fail=1; RWDM_MOVE_OUT=""; }
fi
rwdm_move_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_MOVE_OUT"; }
# rwdm_move_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_move_check() {
  local blk npts zeros; blk="$(rwdm_move_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_MOVE_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_MOVE_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
rwdm_move_check pts 4 "Move base (1,1,1) to destination (4,-3,6) translates every point by (3,-4,5)"
rwdm_move_check typed 4 "Move with the typed vector r2,-7,0.5 (relative to the base point) translates by (2,-7,0.5)"
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_move_sens() {
  local blk; blk="$(rwdm_move_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_MOVE_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_MOVE_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_move_sens
